INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-045','DOC-01','com','active','Rapport skal kunne genereres underveis og etter avslutning; historisk rapport skal kunne bygges fra valgt eksportfil.','01-KRAV-FELLES.md:73',44,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-046','DOC-01','com','active','`Gjør klar for ny gjæring` er en egen handling etter kvittert avslutning og, for reell gjæring, komplett SQLite-par for gjæring/template og HTML-rapport for samme sesjon, filverifisert med størrelse og SHA-256. Filfeil vises og logges; manglende, pågående eller mislykket eksport blokkerer. Demo er eksplisitt unntatt eksportkravet.','01-KRAV-FELLES.md:74',45,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-047','DOC-01','com','active','Ved `Gjør klar` skal avsluttet session frigjøres operativt med append-only release-faktum. Historiske sessiondata beholdes; mutable inputdraft kan nullstilles. Eksportfiler, rapporter og teknisk historikk som skal bevares slettes ikke.','01-KRAV-FELLES.md:75',46,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-048','DOC-01','com','active','Manuelle grunnobservasjoner lagres atomisk via `record_observation`; Start lagrer første SG/temperatur/metode, og ordinære målesett kan inneholde den komplette templatevalgte sensoriske målkontrakten.','01-KRAV-FELLES.md:76',47,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-049','DOC-01','com','active','Hvert nytt manuelt målesett bekreftes komplett. Manglende eller avvikende kriteriegrunnlag kan advare, men operatøren kan fortsatt bekrefte en prosessovergang.','01-KRAV-FELLES.md:77',48,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-050','DOC-01','com','active','Readiness bestemmes av den generiske templatebestemte kriteriemodellen; ingen fast hardkodet AND-/brukerkonklusjonsmodell gjelder på tvers av alle trinn.','01-KRAV-FELLES.md:78',49,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-051','DOC-01','com','active','Kontrolltypers maksimale alder og ugyldiggjørende endringer skal forvaltes per template og kontrolltype.','01-KRAV-FELLES.md:79',50,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-052','DOC-01','com','active','Template bestemmer hvilke målinger/sensoriske observasjoner og grenser som er relevante. Maltsødme er ikke del av gjeldende målemodell, og konkrete terskler skal ikke hardkodes som universelle krav.','01-KRAV-FELLES.md:80',51,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-053','DOC-01','com','active','Manglende eller ikke-bestått kontroll gir rød/advarende informasjon, men kan overstyres med ett trykk; alle aktive advarsler logges.','01-KRAV-FELLES.md:81',52,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-054','DOC-01','com','active','Pakking/tappeklar er ikke eget prosesstrinn i gjeldende modell; avslutning er en separat manuell livsløpshandling.','01-KRAV-FELLES.md:82',53,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-055','DOC-01','com','active','Standardforløpet bruker P8 som kaldkrasj, P9 som bunnfallsdump og P10 som kaldkondisjonering; konkrete inngangskriterier bestemmes av templaten.','01-KRAV-FELLES.md:83',54,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-056','DOC-01','com','active','Det finnes ingen hardkodet trykk-/vakuumsikringsport; relevante trykkkrav må uttrykkes gjennom template/kriterier dersom de innføres.','01-KRAV-FELLES.md:84',55,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-057','DOC-01','com','active','Kaldkondisjonering inngår i alle støttede gjæringsforløp; måltemperatur og varighet bestemmes av templaten.','01-KRAV-FELLES.md:85',56,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-058','DOC-01','com','active','Temperaturøkninger kan modelleres som egne prosesstrinn, mens biologiske faser fortsatt holdes som separat modell.','01-KRAV-FELLES.md:86',57,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-059','DOC-01','com','active','Før livebruk skal Systemkontroll, omstart, sensor-/integrasjonsavbrudd, HA-reconnect, rapport/eksport og minst én komplett testgjæring verifiseres i målmiljøet.','01-KRAV-FELLES.md:87',58,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-060','DOC-01','com','active','Bunnfallsdump inngår som P9 i standardforløpet. Gjærhøsting, gjærsortering, overføring og pakking ligger utenfor prosessmodellen.','01-KRAV-FELLES.md:88',59,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-061','DOC-01','com','active','Manuelt målt temperatur og kjølemaskinens settpunkt lagres som separate observasjonsverdier.','01-KRAV-FELLES.md:89',60,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-062','DOC-01','com','active','Hver brukerinitierte stateful handling skal få en unik operasjons-ID og kunne spores til eksplisitt sluttresultat fra samme operasjon, med tidspunkt, handling, tilstand før/etter, godtatt/avvist, feltfeil, aktive advarsler og teknisk feil. Valideringsavvisning og persistens-/integrasjonsfeil skal skilles.','01-KRAV-FELLES.md:90',61,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-063','DOC-01','com','active','Systemkontrollen skal, når HA-integrasjonen er migrert, sammenligne forventede og faktisk registrerte HA-entity-ID-er og vise mangler og mulige suffikskollisjoner.','01-KRAV-FELLES.md:91',62,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-064','DOC-01','com','active','Stateful operatørhandlinger skal ha korrelasjons-/operasjons-ID der nødvendig for idempotens/sporbarhet og en enkel global 8 s dobbelttrykksguard som dekker normal GUI-/read-model-oppdateringstid. Sensoringest og tekniske systemkommandoer behandles ikke som operatørknappetrykk.','01-KRAV-FELLES.md:92',63,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-065','DOC-01','com','active','Faglige regler som kan variere mellom templateversjoner skal eies deklarativt av registry/template i MariaDB. Node-RED skal ikke hardkode fase-, prosesstrinn-, gjærprofil- eller template-spesifikke terskler, vinduer, persistenskrav eller freshnessgrenser.','01-KRAV-FELLES.md:94',64,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-066','DOC-01','com','active','Hver beregnet metrikk skal ha registrert generisk beregningsmodell, deklarerte input og typed parametere. Motoren implementerer beregningsmodellene generisk, mens MariaDB bestemmer hvilken modell og hvilke verdier som brukes.','01-KRAV-FELLES.md:95',65,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-067','DOC-01','com','active','Freshness og persistens er separate begreper. `maximum_age_minutes` gjelder alder på datagrunnlaget; krav om vedvarende kriterium uttrykkes eksplisitt med persistens-/vindusparametere og skal ikke simuleres som maksimal alder på en fase/state.','01-KRAV-FELLES.md:96',66,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-068','DOC-01','com','active','Automatisk biologisk framdrift er sekvensiell. Motoren vurderer bare neste biologiske fase som overgangskandidat; historisk backfill skal replayes kronologisk og kan ikke hoppe over en mellomliggende B-fase.','01-KRAV-FELLES.md:97',67,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-069','DOC-01','com','active','En aktiv sessions regelvurdering skal kunne reproduceres fra persisterte domenedata og den frosne normaliserte session-planen. Dersom Function-nodekode må tilføre en fagregel som ikke finnes i session-planen, er regelen ikke gyldig implementert.','01-KRAV-FELLES.md:98',68,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-070','DOC-01','com','active','Publisering av template skal avvise kombinasjoner av metrikk, beregningsmodell, kriteriemodell, input, typed parametere og freshness som registry ikke tillater. Motoren skal ikke reparere manglende eller ugyldig regelgrunnlag med skjulte defaults.','01-KRAV-FELLES.md:99',69,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-071','DOC-01','com','active','Operativ observability skal lese det persisterte produksjonsgrunnlaget. Teknisk/Systemkontroll skal ikke opprette en alternativ live-sensorbane eller være konkurrerende produsent av målekildens runtime-status.','01-KRAV-FELLES.md:100',70,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-072','DOC-01','com','active','Måledata med åpenbart ugyldig eller utilstrekkelig grunnlag skal ikke gjøres autoritative ved normalisering/clamping. Valideringsutfall skal være sporbare, mens autoritative tidsserier bare skal inneholde godkjent grunnlag.','01-KRAV-FELLES.md:102',71,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-073','DOC-01','com','active','Utilstrekkelig målegrunnlag vises som manglende. P24r7 publiserer bare ordinære analyseverdier fra faktiske målinger; ingen foreløpige verdier, regresjonsestimater, utfylling eller følsomhetsbånd.','01-KRAV-FELLES.md:103',72,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-074','DOC-01','com','active','Feil eller mangler skal rettes ved den autoritative kilden. Feil/mangler i MariaDB, registry, frozen session, runtimefakta eller read-model skal ikke maskeres med fallback, defaultverdi, korreksjon eller parallell domenelogikk i Node-RED, Home Assistant eller frontend.','01-KRAV-FELLES.md:105',73,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-075','DOC-01','com','active','Krav, beslutninger, verifikasjonskrav, tester og deres relasjoner skal være strukturerte metadata i MariaDB. Faktiske testkjøringer og testresultater skal lagres som egne historiske fakta.','01-KRAV-FELLES.md:106',74,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-076','DOC-01','com','active','Verifikasjonsresultater er append-only. En ny TECH/FUNC/UAT-kjøring skal opprette nye run/result-fakta og skal ikke overskrive tidligere verifikasjonshistorikk.','01-KRAV-FELLES.md:107',75,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-077','DOC-01','com','active','Verifikasjon skal skille eksplisitt mellom tekniske tester, funksjonelle regresjonstester og UAT/målmiljøtest. Testbarhet skal bygges inn i løsningen selv om omfanget av faktisk testkjøring tilpasses endringens risiko og prototypefasen.','01-KRAV-FELLES.md:108',76,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-078','DOC-01','com','active','Verifikasjonsdata skal kunne eksporteres som maskinlesbart datasett og lesbar HTML-rapport fra samme DB-eide snapshot/read-model uten at eksportlaget introduserer alternativ tolkning eller statusberegning.','01-KRAV-FELLES.md:109',77,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-079','DOC-01','com','active','MariaDB, Node-RED og Home Assistant skal behandles som asynkrone moduler som kan være utilgjengelige og komme tilbake i vilkårlig rekkefølge. Når avhengigheter blir tilgjengelige skal Node-RED idempotent rekonstruere og republisere gjeldende tilstand fra MariaDB uten manuell Start, lokal persistent fallback eller duplisert domenhistorikk.','01-KRAV-FELLES.md:110',78,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-080','DOC-01','com','active','Sluttarkiv/rapport skal filverifiseres med størrelse og SHA-256 før verified registreres. Bare metadata sendes tilbake til DB; eksportstørrelsen skal ikke være avhengig av max_allowed_packet. Arkiveringsforsøk og terminalt resultat er append-only fakta.','01-KRAV-FELLES.md:120',79,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-081','DOC-01','com','active','Ingen analyseverdi skal anslås mellom manglende målinger. En beregning fra faktiske målinger er tillatt og skal vise kilde og faktisk måletid; manuell og rå Tilt-basis skal være atskilt.','01-KRAV-FELLES.md:121',80,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-082','DOC-01','com','active','SQLite er filutveksling; importert historikk normaliseres i MariaDB. Motoren bruker ikke et eksternt SQLite-arkiv direkte.','01-KRAV-FELLES.md:127',81,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-COM-083','DOC-01','com','active','Gjærings- og template-arkiv har samme session-/eksportprefix og valideres som et sett. Begge er SQLite; HTML-rapport beholdes.','01-KRAV-FELLES.md:128',82,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
