INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-003','DOC-02','motor','active','Node-RED-restart skal kunne rekonstruere nødvendig nåtilstand fra MariaDB alene.','02-KRAV-MOTOR-OG-INTEGRASJON.md:26',85,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-004','DOC-02','motor','active','HA-entity-ID/config-ID-grensen følger dokument 05 og maskinkontrakten.','02-KRAV-MOTOR-OG-INTEGRASJON.md:27',86,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-005','DOC-02','motor','active','Feil i Node-RED/HA-integrasjonen skal inn i normalisert `technical_events` der persistens er mulig.','02-KRAV-MOTOR-OG-INTEGRASJON.md:28',87,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-006','DOC-02','motor','active','Systemkontroll skal skille faktisk teknisk feil fra funksjon som bevisst ikke er portert; `not_applicable` skal ikke gi falsk FAIL.','02-KRAV-MOTOR-OG-INTEGRASJON.md:29',88,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-007','DOC-02','motor','active','Ingen JSON-blobber skal brukes som erstatning for normaliserte domenedata.','02-KRAV-MOTOR-OG-INTEGRASJON.md:30',89,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-008','DOC-02','motor','active','SG-only gjelder alle aktive grensesnitt.','02-KRAV-MOTOR-OG-INTEGRASJON.md:31',90,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-009','DOC-02','motor','active','Runtimehistorikk skal være append-only der ny faglig tilstand kan uttrykkes som ny fakta-/revisjonsrad. Historiske runtime-rader skal ikke toggles til/fra current.','02-KRAV-MOTOR-OG-INTEGRASJON.md:32',91,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-010','DOC-02','motor','active','Systemet skal ikke innføre applikasjonsstyrt DB-serialisering eller eksplisitt locking (`SELECT ... FOR UPDATE`, `GET_LOCK`) som normal concurrency-mekanisme. InnoDB håndterer samtidige readers/writers.','02-KRAV-MOTOR-OG-INTEGRASJON.md:33',92,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-011','DOC-02','motor','active','Datakonsistens skal primært uttrykkes med normalisering, PK/FK/UNIQUE/CHECK og idempotente operation-ID-er.','02-KRAV-MOTOR-OG-INTEGRASJON.md:34',93,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-012','DOC-02','motor','active','Rene reads kan kjøre parallelt og kan kortvarig se siste committed snapshot. Read-model korrigeres ved neste lesing; dette skal ikke kompenseres med global locking.','02-KRAV-MOTOR-OG-INTEGRASJON.md:35',94,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-013','DOC-02','motor','active','Mutable arbeidskladd er tillatt for operatørinput/template-draft, men skal være tydelig skilt fra immutable sessionhistorikk.','02-KRAV-MOTOR-OG-INTEGRASJON.md:36',95,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-014','DOC-02','motor','active','Ordinær `Start gjæring` skal bruke valgt **Start fra** som opprinnelig pitch-/kildestart og hente tilgjengelig SG-, temperatur-, heartbeat- og RSSI-historikk fra DB-konfigurert Home Assistant-kilde.','02-KRAV-MOTOR-OG-INTEGRASJON.md:37',96,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-015','DOC-02','motor','active','HA-historikk skal normaliseres til komplette 5-minuttersbøtter i `measurements_5m`; rå HA-state skal ikke bli alternativ persistent domenestore.','02-KRAV-MOTOR-OG-INTEGRASJON.md:38',97,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-016','DOC-02','motor','active','Heartbeat-kilden avgjør datadekning. Manglende heartbeat skal gi eksplisitt `measurement_data_gaps`; SG/temperatur skal ikke interpoleres over slike gap.','02-KRAV-MOTOR-OG-INTEGRASJON.md:39',98,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-017','DOC-02','motor','active','Etter Start skal samme inkrementelle import fortsette i en aktiv-session-styrt femminuttersløyfe fra persisted `last_import_cutoff_at`. Uten aktiv reell session skal ingen periodisk HA-history-henting initieres; restart skal kunne hente seg inn fra MariaDB-cursor + HA-historikk når aktiv session finnes.','02-KRAV-MOTOR-OG-INTEGRASJON.md:40',99,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-018','DOC-02','motor','active','Målekildens entity-ID-er skal ligge i MariaDB `measurement_source_profiles`, ikke hardkodes i Node-RED-funksjoner.','02-KRAV-MOTOR-OG-INTEGRASJON.md:41',100,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-019','DOC-02','motor','active','Evaluator skal bruke frosne `session_metric_runtime_*`, `session_biology_calculation_*` og kriterieparametere som deklarativt regelgrunnlag. Metrikk-ID skal ikke brukes som skjult domene-switch for å velge fagregel.','02-KRAV-MOTOR-OG-INTEGRASJON.md:43',101,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-020','DOC-02','motor','active','Node-RED implementerer generiske måleberegninger: SG-fall, utgjæringsgrad, signert endepunktrate, maks–min-stabilitet og state-order. Modellvalg, kilder, terskler og vindusparametere kommer fra frozen MariaDB-data. Frontend beregner ingen domenemetrikker.','02-KRAV-MOTOR-OG-INTEGRASJON.md:44',102,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-021','DOC-02','motor','active','En metrikk med `freshness_mode=not_applicable` skal ikke kunne evalueres med `maximum_age_minutes`; dette skal oppdages som ugyldig konfigurasjon ved templatevalidering/publisering.','02-KRAV-MOTOR-OG-INTEGRASJON.md:45',103,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-022','DOC-02','motor','active','Ved HA-history-backfill skal biologimotoren evaluere 5-minuttersgrunnlaget kronologisk, håndheve persistens over faktisk sammenhengende datadekning og opprette hvert sekvensielle biologiske visit/transition ved det historiske kriteriekryssingstidspunktet.','02-KRAV-MOTOR-OG-INTEGRASJON.md:46',104,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-023','DOC-02','motor','active','Persistens skal resettes over registrerte `measurement_data_gaps`; et krav om vedvarende kriterium kan ikke oppfylles ved å akkumulere tid på tvers av et dokumentert datagap.','02-KRAV-MOTOR-OG-INTEGRASJON.md:47',105,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-024','DOC-02','motor','active','`sensor.gjaeringsassistent_malekilde` skal produseres fra én dedikert MariaDB-read-model. Live-ingest og Systemkontroll kan trigge refresh/kontroll, men skal ikke publisere egne konkurrerende målekildetilstander.','02-KRAV-MOTOR-OG-INTEGRASJON.md:48',106,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-025','DOC-02','motor','active','Uten aktiv reell session skal målekildens operative importstatus være `IDLE` og ingen sensorhistorikk hentes for observability. Aktiv reell session uten persistert kildebinding skal være feiltilstand, ikke `IDLE`.','02-KRAV-MOTOR-OG-INTEGRASJON.md:49',107,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-026','DOC-02','motor','active','Ved historisk HA-history/catch-up skal prosesstrinn replayes kronologisk og sekvensielt på samme grunnprinsipp som B-faser. Bare neste aktive P-kandidat kan opprettes, og vurderingen skal bruke målinger, observasjoner og biologisk tilstand som var tilgjengelige ved evalueringstidspunktet. Etter catch-up/live er ordinær P-overgang fortsatt operatørbekreftet.','02-KRAV-MOTOR-OG-INTEGRASJON.md:50',108,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-027','DOC-02','motor','active','`Start gjæring` skal ha sporbar ingress og eksplisitt slutt-/feilkvittering. DB-/bindingfeil i Start-kjeden skal nå normalisert Technical-pipeline og startstatus; taus bortfall av en stateful Start-kommando er ikke tillatt.','02-KRAV-MOTOR-OG-INTEGRASJON.md:51',109,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-028','DOC-02','motor','active','Historisk evaluator skal bruke persistert importcutoff som øvre evalueringshorizon; live evaluator skal bruke MariaDB-klokken. Node-REDs lokale veggklokke skal ikke være fallback for faglig freshness/alder.','02-KRAV-MOTOR-OG-INTEGRASJON.md:52',110,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-029','DOC-02','motor','active','Gjennomført B/P-overgang skal presenteres fra transitionens eksakte `evaluation_id`; current candidate evaluation er et separat read-model-faktum og skal ikke erstatte historisk overgangsbevis.','02-KRAV-MOTOR-OG-INTEGRASJON.md:53',111,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-030','DOC-02','motor','active','Releasebygging skal kjøre maskinell arkitekturkonformitetskontroll for sentrale DB-only-, evalueringshorizon- og read-model-regler. Kontrollen er en utviklings-/releaseport og skal ikke legges inn i installeren.','02-KRAV-MOTOR-OG-INTEGRASJON.md:54',112,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-031','DOC-02','motor','active','Runtime-/rapportverdier som vises til operatøren skal komme ferdig beregnet og ferdig representert fra MariaDB/read-model. Frontend skal ikke beregne, korrigere, tolke, formatere eller supplere domenedata med fallbackverdier.','02-KRAV-MOTOR-OG-INTEGRASJON.md:55',113,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-032','DOC-02','motor','active','En registrert metrikk skal ha én autoritativ beregningsbane. Oversikt, B/P-vurdering og rapport skal lese persistert evaluator-/metric-resultat; samme domeneverdi skal ikke beregnes på nytt i frontend eller parallell Node-RED read-model.','02-KRAV-MOTOR-OG-INTEGRASJON.md:56',114,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-033','DOC-02','motor','active','Kriterieevaluering skal persistere datagrunnlagets provenance, inkludert relevant vindu, sample count, faktisk dekning og siste sample. MariaDB-read-model skal produsere ferdig `data_window_display`; frontend skal bare vise feltet.','02-KRAV-MOTOR-OG-INTEGRASJON.md:57',115,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-034','DOC-02','motor','active','Aktiv gjæring skal kunne generere en HTML snapshotrapport fra MariaDB/read-model uten lifecycle-endring. Rapportverdier skal være de samme ferdige displayverdiene som den operative read-modelen leverer.','02-KRAV-MOTOR-OG-INTEGRASJON.md:58',116,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-035','DOC-02','motor','active','Målekilde/Tilt-status skal leses fra ett MariaDB-view. Node-RED kan normalisere transportformen fra mysql-node, men skal ikke konstruere alternativ målekildestatus, timestamps eller domenedisplay.','02-KRAV-MOTOR-OG-INTEGRASJON.md:59',117,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-036','DOC-02','motor','active','Historisk automatisk prosesstrinnsovergang skal være en eksplisitt egenskap ved hvert template-prosesstrinn og fryses til session. Historisk evaluator kan vurdere alle neste trinn, men kan bare persistere overgang når det frosne trinnet eksplisitt tillater historisk autoovergang.','02-KRAV-MOTOR-OG-INTEGRASJON.md:60',118,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-037','DOC-02','motor','active','W-34/70 standardtemplaten tillater historisk etablering av P1/P2. P3 og senere trinn krever operatørbekreftet overgang selv om kriteriene er oppfylt.','02-KRAV-MOTOR-OG-INTEGRASJON.md:61',119,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-038','DOC-02','motor','active','Historisk HA-import skal sekvensieres som persistér chunk → biologisk evaluering → prosessevaluering → neste chunk. Evaluator-/recommendation-identiteter skal komme fra MariaDB og ikke konstrueres fra Node-RED-klokke.','02-KRAV-MOTOR-OG-INTEGRASJON.md:62',120,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-039','DOC-02','motor','active','Åpent måledatagap skal ha én autoritativ representasjon i `measurement_data_gaps`. `session_measurement_sources` skal ikke cache duplisert gapstatus.','02-KRAV-MOTOR-OG-INTEGRASJON.md:63',121,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-040','DOC-02','motor','active','Validering av rå måleprøver skal være metadata-styrt per målekilde og fryses til session. Motoren kan implementere registrerte generiske valideringsmodeller, men signal-/template-spesifikke grenser skal ikke hardkodes.','02-KRAV-MOTOR-OG-INTEGRASJON.md:64',122,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-041','DOC-02','motor','active','Ugyldige råprøver skal forkastes før autoritativ `measurements_5m`-lagring; systemet skal ikke clamp-e eller erstatte en ugyldig verdi med en oppdiktet plausibel verdi. Kvalitetsutfall skal være sporbare separat.','02-KRAV-MOTOR-OG-INTEGRASJON.md:65',123,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-042','DOC-02','motor','active','Autoritativ SG i en godkjent 5-minuttersbøtte skal være robust aggregert fra godkjente prøver; W-34/70/Tilt bruker median. Min/middel/maks er diagnostikk og skal beregnes fra samme godkjente prøvesett.','02-KRAV-MOTOR-OG-INTEGRASJON.md:66',124,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-043','DOC-02','motor','active','Om en beregnet verdi skal ha analyseserie/graf og dens presentasjons-/behandlingsregler skal ligge i template/sessionmetadata. Motor/frontend skal ikke ha graph-ID-spesifikke regler.','02-KRAV-MOTOR-OG-INTEGRASJON.md:67',125,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-044','DOC-02','motor','active','Analyse publiserer bare verdier som oppfyller frozen minste antall, tidsspenn og dekning. Rate beregnes fra målte endepunkter og faktisk tid; ingen kortvindu-estimat eller foreløpig publisering.','02-KRAV-MOTOR-OG-INTEGRASJON.md:68',126,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-045','DOC-02','motor','active','`analysis_series_values` er append-only. Ugyldige beregnede outputs skal ikke clampes/persisteres som gyldig serie; avvisningen skal registreres som analysevalideringsfaktum.','02-KRAV-MOTOR-OG-INTEGRASJON.md:69',127,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-046','DOC-02','motor','active','HA-projeksjoner skal bare eksponere attributtverdier som er gyldige i HA-kontrakten. Nullable interne råfelt skal erstattes av DB-eide ferdige presentasjonsfelt eller utelates, ikke få Node-RED-fallback.','02-KRAV-MOTOR-OG-INTEGRASJON.md:70',128,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-047','DOC-02','motor','active','Gyldighetsdomene for avledede metrics skal være normalisert metric-metadata og fryses til template/session. Samme frozen grenser skal håndheves før en metric kan brukes av B/P-kriterier og før den kan persisteres i analyseserie. Ugyldig output skal gi manglende/ugyldig datagrunnlag, aldri overgang eller clampet verdi.','02-KRAV-MOTOR-OG-INTEGRASJON.md:71',129,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-048','DOC-02','motor','active','Node-RED skal registrere UAT-resultater gjennom validert MariaDB-operasjon mot aktive `UAT`-tester; frontend-event er bare ingress og er ikke kvittering på lagring.','02-KRAV-MOTOR-OG-INTEGRASJON.md:73',130,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-049','DOC-02','motor','active','Gjeldende test-, verifikasjons- og kravstatus skal utledes i MariaDB read-models. Node-RED og frontend skal ikke beregne egen coverage, samlet kravstatus eller fallback-status.','02-KRAV-MOTOR-OG-INTEGRASJON.md:74',131,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-050','DOC-02','motor','active','Automatisk releaseverifikasjon skal kunne representeres med stabile `TEST-TECH-*`/`TEST-FUNC-*`-identiteter og knyttes til verifikasjonskrav; målmiljøtest skal bruke `TEST-UAT-*`.','02-KRAV-MOTOR-OG-INTEGRASJON.md:75',132,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-051','DOC-02','motor','active','Verifikasjonseksport skal lese ett konsistent DB-grunnlag med metadata, relasjoner, testkjøringer og resultater og produsere JSON og HTML uten domenelogikk i renderer.','02-KRAV-MOTOR-OG-INTEGRASJON.md:76',133,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-052','DOC-02','motor','active','Forventet gjæringsresultat skal uttrykkes normativt som templateens intervall for tilsynelatende utgjæringsgrad. Forventet FG skal beregnes fra faktisk korrigert OG og dette intervallet; operatøren skal ikke registrere et uavhengig FG-mål ved Start.','02-KRAV-MOTOR-OG-INTEGRASJON.md:77',134,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-053','DOC-02','motor','active','Operativ gjæringsprosent skal være tilsynelatende utgjæringsgrad. Egen FG-fremdriftsprosent, rate relativt til historisk maksimum og absolutt SG-rate skal ikke være operative domenemetrikker.','02-KRAV-MOTOR-OG-INTEGRASJON.md:78',135,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-054','DOC-02','motor','active','Målefreshness og generell målekvalitet skal behandles som en felles evalueringsforutsetning. Manglende eller foreldet livegrunnlag skal gi «kan ikke evalueres»/ufullstendig vurdering, ikke falskt biologisk eller prosessuelt kriterium.','02-KRAV-MOTOR-OG-INTEGRASJON.md:79',136,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-055','DOC-02','motor','active','Biologiske kriterier skal bruke et lite forklarbart kjernesett av SG-fall, signert SG-rate, tilsynelatende utgjæringsgrad og SG-stabilitet. Prosesstrinn skal normalt konsumere ferdig biologisk fase og bare legge til operative betingelser; samme biologiske logikk skal ikke dupliseres i P-kriterier.','02-KRAV-MOTOR-OG-INTEGRASJON.md:80',137,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-056','DOC-02','motor','active','MAD-validering bruker deklarert støygulv også ved null MAD. B/P og Analyse bruker identisk endpoint_rate_v1 fra felles kilde: målt SG-forskjell / faktisk tid, ingen regresjon eller følsomhetsbånd. Datagap bryter vinduet.','02-KRAV-MOTOR-OG-INTEGRASJON.md:82',138,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-057','DOC-02','motor','active','Rå Tilt-utgjæringsgrad bruker faktisk OG og godkjent Tilt-SG uten pitch-kalibrering. Manuell utgjæringsgrad bruker faktisk OG og korrigert manuell SG. Kildene er separate og velges eksplisitt av templatekriteriets metric_id; ingen kildebytte/fallback.','02-KRAV-MOTOR-OG-INTEGRASJON.md:83',139,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-058','DOC-02','motor','active','Aktuelle analyseverdier skal hentes fra siste godkjente analyseserie og kontrolleres mot nyere avvisning/freskhet; overgangskriteriers gamle snapshots skal ikke presenteres som aktuell rate. Rå Tilt-AA og manuell AA har hvert sitt faktiske målegrunnlag og måletid; ingen automatisk kildebytte.','02-KRAV-MOTOR-OG-INTEGRASJON.md:84',140,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-059','DOC-02','motor','active','Tomme valgfrie korreksjonsparametere skal lagres eksplisitt som ikke angitt, uten konvertering til nulltallet. Hele konfigurasjonen skal valideres før transaksjonen. Ved ugyldig kriteriekonfigurasjon skal fortsatt beregnbar faktisk verdi og forklarende årsak bevares.','02-KRAV-MOTOR-OG-INTEGRASJON.md:85',141,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-060','DOC-02','motor','active','S-04- og M42-templater skal være egne publiserte normaliserte profiler med kjølig hovedgjæring innen produsentområdet, gradvis opprydding ved 20 °C og eksplisitte sluttkontroller. 21 dager er planleggingsramme, ikke automatisk ferdigregel.','02-KRAV-MOTOR-OG-INTEGRASJON.md:95',142,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-061','DOC-02','motor','active','HA-timesstatistikk lagres append-only med reelle min/gjennomsnitt/maks, uten krav om historisk MQTT-heartbeat og uten konstruerte medianer/prøveantall.','02-KRAV-MOTOR-OG-INTEGRASJON.md:101',143,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-062','DOC-02','motor','active','Hver Systemkontroll lagrer alle resultater atomisk med unik kjøringsidentitet og kontrollerer HA mot et ferskt API-svar.','02-KRAV-MOTOR-OG-INTEGRASJON.md:102',144,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-063','DOC-02','motor','active','Aktiv og avsluttet rapport bruker én generator og inkluderer full kronologisk hendelseshistorikk og tilgjengelige timesdata.','02-KRAV-MOTOR-OG-INTEGRASJON.md:103',145,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-064','DOC-02','motor','active','Datasett- og sammenligningsvalg persisteres i MariaDB; den valgte demoidentiteten fryses ved Start.','02-KRAV-MOTOR-OG-INTEGRASJON.md:104',146,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-065','DOC-02','motor','active','Graftransport skal dele presentasjonsmetadata, bruke kompakt JSON og tilby verifisert gzip. Punktutvalg skjer i DB og bevarer første/siste/min/maks og segmentgrenser. Lagring/analyser beholder femminuttersoppløsning; standard visningsintervall er 30 minutter.','02-KRAV-MOTOR-OG-INTEGRASJON.md:110',147,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-066','DOC-02','motor','active','HA-timesstatistikk hentes ved første historiske import og ved DB-målt etterslep på minst én time. Vanlig frisk femminuttersimport henter detaljhistorikk. En uløst statistikkfeil gir nytt historisk forsøk; gjenoppretting registreres bare når en slik feil faktisk er aktiv.','02-KRAV-MOTOR-OG-INTEGRASJON.md:116',148,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-067','DOC-02','motor','active','Import av gjæring og tilhørende template skjer atomisk med ny lokal identitet og historisk frigivelse. Feil ruller tilbake hele importen; aktiv gjæring og måleskriving påvirkes ikke.','02-KRAV-MOTOR-OG-INTEGRASJON.md:122',149,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-068','DOC-02','motor','active','Importert template får alltid en egen unik ID og kildeproveniens; den sammenlignes, dedupliseres eller flettes ikke med eksisterende templates. Redigering krever egen kopi.','02-KRAV-MOTOR-OG-INTEGRASJON.md:123',150,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-069','DOC-02','motor','active','Startstatus rekonstrueres fra MariaDB ved demo, import, avslutning, klargjøring og omstart. Systemkontroll skal oppdage vedvarende motstridende HA-status.','02-KRAV-MOTOR-OG-INTEGRASJON.md:129',151,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-070','DOC-02','motor','active','Hele historiske sesjoner kan slettes atomisk med alle tilhørende data. Aktiv sesjon er beskyttet; gjeldende sammenligningsvalg nullstilles ved sletting. Append-only gjelder innenfor beholdte sesjoner.','02-KRAV-MOTOR-OG-INTEGRASJON.md:130',152,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-071','DOC-02','motor','active','Aktiv eksport produserer et merket konsistent øyeblikksbilde av gjæring, template og felles HTML-rapport uten å avslutte sesjonen. Begge SQLite-filer får SHA-256-sidefil.','02-KRAV-MOTOR-OG-INTEGRASJON.md:131',153,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-072','DOC-02','motor','active','Manglende, uleselig eller feil ekstern SHA gir synlig advarsel uten å blokkere import. SQLite-integritet, skjema, eksportpar og transportkontrollsum valideres fortsatt.','02-KRAV-MOTOR-OG-INTEGRASJON.md:132',154,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-073','DOC-02','motor','active','En historisk HA-sesjon har fra-tid fra gjeldende pitchrevisjon og en eksplisitt slutt i session_history_windows. Importen stopper ved sluttgrensen, også etter omstart. Sluttgrensen valideres i DB og avgrenser lagring; ingen normal live-import planlegges etter fullføring.','02-KRAV-MOTOR-OG-INTEGRASJON.md:138',155,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-074','DOC-02','motor','active','Effektiv P/B-slutt er neste visits gjeldende start innen samme tidslinje. Siste visit avgrenses av DB-eid sesjonsklokke. MariaDB beregner datoer og varighet for dashboard og rapport; korreksjon beholder tidligere revisjoner.','02-KRAV-MOTOR-OG-INTEGRASJON.md:139',156,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-075','DOC-02','motor','active','Historiske vurderinger, grafakser og manuelle registreringer bruker den historiske horisonten, ikke dagens klokke. Måle-/hendelsestid og faktisk registreringstid bevares separat. Manglende data og delvis ubrukelig timesstatistikk skal ikke fylles ut med estimater.','02-KRAV-MOTOR-OG-INTEGRASJON.md:140',157,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-076','DOC-02','motor','active','Klassifisering av målekildestatus eies av normalisert MariaDB-policy og read-model. Ukjent statuspolicy eller manglende påkrevd kontrollgrunnlag skal være synlig feil, uten lokal Node-RED-liste eller fallback.','02-KRAV-MOTOR-OG-INTEGRASJON.md:149',158,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-077','DOC-02','motor','active','Ferdig behandlet importperiode skal skilles fra faktisk datadekning. Antall og tidsgrenser for ordinære femminuttersmålinger og timesstatistikk samt registrerte rådatagap utledes i DB. Timesstatistikk skal ikke fremstilles som ordinært B/P-grunnlag.','02-KRAV-MOTOR-OG-INTEGRASJON.md:150',159,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-078','DOC-02','motor','active','Forbigående HA-publiseringsbrudd journalføres uten rekursiv publisering av feilen. Nytt forsøk leser ferske DB-projeksjoner, aldri en lokal domenekø. Et konkret publiseringsproblem lukkes først etter vellykket utgang fra den berørte HA-noden. Ugyldig payload skal fortsatt være feil.','02-KRAV-MOTOR-OG-INTEGRASJON.md:151',160,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-079','DOC-02','motor','active','Sensorbindinger normaliseres per signal, enhet og konfigurasjonsrevisjon i MariaDB, og fryses per reell sesjon. Livebytte trer i kraft ved en DB-bestemt femminuttersgrense; tidligere bindinger og målinger beholdes. Historisk import endres ikke retroaktivt.','02-KRAV-MOTOR-OG-INTEGRASJON.md:157',161,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-MOTOR-080','DOC-02','motor','active','Trykk er manuelt til en kompatibel HA-sensor er valgt. Sensortrykk omregnes fra deklarert enhet til bar med DB-eide koeffisienter og grenser. Fravær av valgfritt trykk skal ikke blokkere SG/temperatur. B/P-fravik lagres i en felles kort DB-transaksjon med gjeldende evaluering, kriterierevisjon og eksplisitt bekreftelse.','02-KRAV-MOTOR-OG-INTEGRASJON.md:158',162,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
