INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-011','DOC-03','ha','active','Node-RED-motoren validerer operatørgrunnlaget mot MariaDB og persisterer atomiske domeneoperasjoner i MariaDB. HA/dashboard er operatør-/presentasjonslag og skal ikke være alternativ domenemotor eller sannhetskilde.','03-KRAV-DASHBOARD.md:55',173,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-012','DOC-03','ha','active','Custom-kortet skal hente en eksplisitt read-model som er avledet fra kvitterte MariaDB-data via Node-RED. Transportformatet kan utvikles videre, men frontendprojeksjonen er aldri persistent autoritet.','03-KRAV-DASHBOARD.md:56',174,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-013','DOC-03','ha','active','Historisk sammenligning skal lese eksplisitt valgt eksport read-only, justere tidsforløp etter lagrede ankere og aldri aktivere eller endre den historiske sesjonen.','03-KRAV-DASHBOARD.md:57',175,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-014','DOC-03','ha','active','Node-RED-status eksponeres som direkte HA-entiteter via WebSocket-integrasjonen, ikke via MQTT Discovery.','03-KRAV-DASHBOARD.md:58',176,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-015','DOC-03','ha','active','Gjæringsmotoren skal ikke bruke MQTT Discovery for sine HA-statusentiteter. Sensoringest kan bruke relevant transport, mens operatør-/statusentiteter opprettes av Node-RED gjennom HA WebSocket-integrasjonen.','03-KRAV-DASHBOARD.md:59',177,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-016','DOC-03','ha','active','Statuslaget omfatter system/sesjon, biologisk fase/kandidat/sikkerhet, aktiv/anbefalt prosess, tilsynelatende utgjæringsgrad, SG-hastighet, datakvalitet, målingsalder, anbefaling og alarm.','03-KRAV-DASHBOARD.md:60',178,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
