INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-018','DOC-03','ha','active','Tidskorrigering for biologiske faser bruker valgt registrering og dato/tid, uten begrunnelseskrav. Originalt, manuelt og effektivt tidspunkt skal kunne vises og overstyringen kunne fjernes.','03-KRAV-DASHBOARD.md:62',180,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-019','DOC-03','ha','active','Dashboardets målstruktur har åtte faner: `Gjæring`, `Biologi`, `Prosesstrinn`, `Analyse`, `Måleresultater`, `Template`, `Verifikasjon` og `Teknisk`.','03-KRAV-DASHBOARD.md:63',181,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
