INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-035','DOC-03','ha','active','Dashboardet skal bruke korte visningsnavn; prefikset «Gjæringsassistent» skal ikke gjentas i hver rad.','03-KRAV-DASHBOARD.md:79',197,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-036','DOC-03','ha','active','Templatefanen skal være grafisk og administrere/redigere normaliserte template-data gjennom Node-RED-motorens MariaDB-operasjoner, ikke et JSON-tre. Registry skal styre tilgjengelige metrics/modeller/parametere, og valideringsfeil skal vises konkret ved relevant felt og samlet før publisering.','03-KRAV-DASHBOARD.md:80',198,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-037','DOC-03','ha','active','Skjulte livsløpskort skal ikke etterlate misvisende tomme kontrollflater; brukeren skal se hvorfor en handling ikke er tilgjengelig.','03-KRAV-DASHBOARD.md:81',199,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-038','DOC-03','ha','active','Graf-/hendelsesmarkører skal vise faktiske observasjoner, anbefalinger og utførte prosesshandlinger med tidspunkt. Frozen plan endres ikke underveis.','03-KRAV-DASHBOARD.md:82',200,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-039','DOC-03','ha','active','Dashboardet prioriteres for stor skjerm. Måle- og prosesskort kan være brede selv om mobilvisningen blir lengre.','03-KRAV-DASHBOARD.md:83',201,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
