INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-045','DOC-03','ha','active','Biologitabellen viser regel, parameter, aktuell verdi, terskel, vedvarende tid, datakvalitet, status, venteforklaring, kilde, regeltype og usikkerhet.','03-KRAV-DASHBOARD.md:89',207,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-046','DOC-03','ha','active','Prosesstrinnkortet leser kontrollport, vilkår, vurdering og tillatte handlinger fra en MariaDB-avledet read-model publisert via Node-RED og skal ikke være avhengig av hardkodede status-entity-ID-er for å kunne tegnes.','03-KRAV-DASHBOARD.md:90',208,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-047','DOC-03','ha','active','`Måleresultater` skal ha en tydelig `Lagre målinger`-handling som lagrer ett komplett atomisk målesett; ved valideringsfeil beholdes alle inndata.','03-KRAV-DASHBOARD.md:91',209,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-048','DOC-03','ha','active','Prosesstrinnoversikten skal minst ha kolonnene `P`, `Status` og `Prosesstrinn`, og dessuten vise inngangsvilkår, vurdering, målverdier for temperatur/trykk, faktisk start og faktisk varighet uten at disse blandes sammen.','03-KRAV-DASHBOARD.md:92',210,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-049','DOC-03','ha','active','Kortet for utløser/kontrollport/manuell overgang skal vise hva som utløser vurderingen, hvilke kriterier som er oppfylt/venter/advarer, og hvilke manuelle handlinger som er tillatt.','03-KRAV-DASHBOARD.md:93',211,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-050','DOC-03','ha','active','`Vurdering av neste prosesstrinn` skal vise anbefalt neste trinn og anbefalte temperatur-/trykkmål med begrunnelse og datagrunnlag.','03-KRAV-DASHBOARD.md:94',212,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-051','DOC-03','ha','active','`Teknisk` skal ha en samlet strøm/logg for tekniske feil og avvik fra ulike deler av systemet, med tidspunkt, kilde, alvorlighet, melding og relevant kontekst. Denne fungerer som en lesbar teknisk hendelses-/debugflate og er separat fra aktiv oppmerksomhetsstatus.','03-KRAV-DASHBOARD.md:95',213,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-052','DOC-03','ha','active','Før Start skal `Gjæring` samle templatevalg, startgrunnlag og første målesett i samme livsløpsflate. Første målesett skal ligge nederst i Start-flaten, og alternative tetthetsskalaer skal ikke introduseres; hele brukerflaten er SG-basert.','03-KRAV-DASHBOARD.md:96',214,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-053','DOC-03','ha','active','Ved aktiv session skal `Gjæring` tilby eksplisitt **Avslutt gjæring**. Etter kvittert avslutning skal en egen `completed`-flate vises og nye gjæringsmålinger være utilgjengelige.','03-KRAV-DASHBOARD.md:97',215,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-054','DOC-03','ha','active','Completed-flaten skal tilby **Gjør klar for ny gjæring**. Reell session skal vise/svare på eksportgaten; demo kan frigjøres uten eksport.','03-KRAV-DASHBOARD.md:98',216,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-055','DOC-03','ha','active','Kriterietabellene i Biologi og Prosesstrinn skal vise **Datavindu** som kompakt beskrivelse av faktisk vurderingsgrunnlag. `window_median_range` viser vinduslengde og antall datapunkter; `stability_window` viser vinduslengde, faktisk tidsdekning og antall datapunkter. Rå timestamp skal ikke brukes som erstatning for datavindu.','03-KRAV-DASHBOARD.md:99',217,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-056','DOC-03','ha','active','En akseptert operatørkommando skal ha enkel global gjentakelsesbeskyttelse i 8 sekunder slik at nytt klikk ikke sendes mens GUI/read-model normalt rekker å oppdatere. Beskyttelsen er flyktig UI/runtime-tilstand og erstatter ikke `operation_id`/DB-constraints.','03-KRAV-DASHBOARD.md:100',218,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-057','DOC-03','ha','active','Kriteriestatus skal skille faktisk `Konfigurasjonsfeil` fra `Mangler grunnlag`, `For lite grunnlag`, `Foreldet`, `Ikke oppfylt`, `Oppfylt` og `Ikke vurdert`. Frontend skal bruke persistert evaluatorstatus, ikke utlede alle `valid=0` som konfigurasjonsfeil.','03-KRAV-DASHBOARD.md:101',219,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-058','DOC-03','ha','active','Aktiv kriteriekorreksjon og registrert kriteriefravik skal være tydelig visuelt markert direkte ved kriteriet. Markeringen skal ikke erstatte eller farge om selve oppfylt/ikke-oppfylt-statusen.','03-KRAV-DASHBOARD.md:102',220,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-059','DOC-03','ha','active','Målehistorikken skal vise persistente SG-, temperatur-, prosess- og sensorikkfakta eksplisitt, inkludert nærmeste Tilt-SG og ΔSG for manuell korrigert SG når et tidsmessig relevant Tilt-punkt finnes. Horisontal scrolling er tillatt fremfor sammenslåtte kryptiske kolonner.','03-KRAV-DASHBOARD.md:103',221,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-060','DOC-03','ha','active','Fanen **Analyse** skal ligge mellom Prosesstrinn og Måleresultater og tegne de analysene den aktive sessionens metadata deklarerer. Grafene viser den avledede verdien selv; label, forklaring, enhet, serie, B/P-markører, kriterieterskler og gap-policy leveres fra DB-read-model. Under hver graf skal de B-/P-trinnene som bruker analysen vises med kriterium, rolle, krav og tidspunkt kravet først ble oppfylt. Samme requirements-read-model skal drive både terskellinjer/oppfyllelsesmarkører og tabellen. Frontend skal ikke kjenne W-34/70s graf-ID-er eller beregne analysen.','03-KRAV-DASHBOARD.md:104',222,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-061','DOC-03','ha','active','Template-fanen skal ha et komplett templatebibliotek med lifecycle `draft/published/retired`, statusfilter, åpning av eksisterende versjoner, ny draft/ny template, publisering, forkasting, retire og reaktivering. Template-administrasjonens valgte versjon skal være MariaDB-persistet og uavhengig av Start-valget og aktiv session. Publisering skal ikke implisitt endre Start-valget.','03-KRAV-DASHBOARD.md:105',223,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-062','DOC-03','ha','active','Dashboardet skal ha egen `Verifikasjon`-fane som viser DB-eid status for krav → verifikasjonskrav → test/resultat og kan filtrere TECH/FUNC/UAT.','03-KRAV-DASHBOARD.md:151',224,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-063','DOC-03','ha','active','Teknisk-fanen skal vise et kompakt verifikasjonssammendrag med siste DB-eide status og lenke/henvisning til detaljfanen.','03-KRAV-DASHBOARD.md:152',225,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-064','DOC-03','ha','active','UAT skal kunne registreres fra Verifikasjon-fanen med `pass/fail/blocked/not_run`, operatørnavn, notat og eventuell evidensreferanse. Registreringen skal gi ny DB-kvittert append-only resultatrad.','03-KRAV-DASHBOARD.md:153',226,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-065','DOC-03','ha','active','Verifikasjon-fanen skal kunne bestille eksport av strukturert JSON og lesbar HTML-rapport. Frontend skal bare bestille og vise DB/read-model-resultatet, ikke beregne rapportinnhold.','03-KRAV-DASHBOARD.md:154',227,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-066','DOC-03','ha','active','Startflaten skal vise templateens forventede utgjæringsområde og FG-området som er beregnet fra faktisk OG som read-only informasjon. Operatøren skal ikke måtte beregne eller skrive inn forventet FG.','03-KRAV-DASHBOARD.md:155',228,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-067','DOC-03','ha','active','Analyse-grafer skal bruke DB-eide aksemetadata for vertikal minimum/maksimum/tick-intervall og DB-eid `+dag · dato`-merking horisontalt. Grafbeskrivelsen skal forklare hva verdien måler, hvordan den tolkes og hvorfor den er relevant.','03-KRAV-DASHBOARD.md:156',229,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-068','DOC-03','ha','active','Alle tidsseriegrafer i Gjæring og Analyse skal bruke MariaDB/read-model-eid dynamisk Y-akse beregnet fra faktisk min/maks samt relevante mål-/kriteriegrenser. Aksen skal ha liten normal tegnemargin og skal ikke få kunstig minimumsspenn for å skjule variasjon.','03-KRAV-DASHBOARD.md:157',230,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-069','DOC-03','ha','active','Analyse viser ingen estimerte min–maks-/følsomhetsbånd. Målt variasjon kan vises som faktisk spredning i Gjæringsfanens rådatagrafer. Graphpolicy fryses i MariaDB.','03-KRAV-DASHBOARD.md:158',231,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-070','DOC-03','ha','active','Analysegrafer viser kun ordinære verdier fra godkjente målinger. Manglende grunnlag er synlig; ingen foreløpig kurve, utfylling eller interpolasjon over datagap.','03-KRAV-DASHBOARD.md:159',232,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-071','DOC-03','ha','active','SG-rate vises med DB-eid nedre Y-grense 0 og automatisk øvre grense. Negative målebaserte rater beholdes i databasen og i siste-verdi-feltet; de erstattes ikke med absoluttverdi eller null.','03-KRAV-DASHBOARD.md:160',233,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-072','DOC-03','ha','active','Kriteriekorreksjon og kriteriefravik skal følge p22-arbeidsformen. Notat er valgfritt og tomt notat skal ikke avvise handlingen; korreksjon/fravik skal vises separat fra kriteriets faktiske `met/not_met`-status.','03-KRAV-DASHBOARD.md:161',234,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-073','DOC-03','ha','active','Teknisk-fanen skal tilby separat **Eksporter måledata** for aktiv session. Eksporten bygges fra MariaDB og omfatter sessiongrunnlag, 5-minuttersmålinger med min/middel/median/maks der tilgjengelig samt registrerte datagap.','03-KRAV-DASHBOARD.md:162',235,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-074','DOC-03','ha','active','Manuelle utgjæringskontroller vises som separate punkter i samme graf som rå Tilt-serien, med faktisk måletid. Punktserie bindes ikke sammen til en oppdiktet kontinuerlig manuell kurve.','03-KRAV-DASHBOARD.md:177',236,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-075','DOC-03','ha','active','Dashboard, aktiv rapport og sluttrapport bruker samme DB-eide horisontale tidsakse fra effektivt pitchtidspunkt. Før første beregnbare verdi vises en tom graf med akse. Datagap bryter linjer og bånd.','03-KRAV-DASHBOARD.md:178',237,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-076','DOC-03','ha','active','Aktiv gjæring skal samle batch/gjær, volum/OG, effektiv pitch og varigheter, B/P-status, rå Tilt-SG, én aktuell utgjæringsgrad, estimert ABV nå, fersk 24-timersrate, 24/48-timersstabilitet og neste prosesstrinn med årsak/vurderingstid. Verdier og basis leveres av read-model; rapporthandlinger ligger nederst.','03-KRAV-DASHBOARD.md:184',238,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-077','DOC-03','ha','active','SG-stabilitet har generelle 24-/48-timerskurver på faktiske sammenhengende målinger. Verdien er maks–min i SG-poeng, uten bånd, kortvindu-oppskalering eller faseanker. Minste tidsdekning og dynamiske akser eies av DB.','03-KRAV-DASHBOARD.md:185',239,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-078','DOC-03','ha','active','Over hver analysegraf vises MariaDB-forberedt siste gyldige verdi, enhet og faktisk måletid for hver serie. Manglende grunnlag vises uttrykkelig; siste måling fremstilles ikke som en ny måling nå.','03-KRAV-DASHBOARD.md:187',240,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-079','DOC-03','ha','active','Avsluttet gjæring skal vise DB-eid arkivstatus og støtte nytt arkiveringsforsøk uten ny avslutning. Uverifisert sluttarkiv skal fortsatt blokkere Gjør klar for reell gjæring og inngå vedvarende i Systemkontroll.','03-KRAV-DASHBOARD.md:188',241,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-080','DOC-03','ha','active','Grafene kan sammenligne med et referansedatasett eller en avsluttet gjæring, justert til tid siden pitch og med egne analyseverdier.','03-KRAV-DASHBOARD.md:194',242,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-081','DOC-03','ha','active','Grafvisningen kan velge 5/15/60-minutters detaljvisning og hele gjæringen/siste 24 timer/48 timer/7 dager uten å endre lagrede målinger.','03-KRAV-DASHBOARD.md:195',243,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-082','DOC-03','ha','active','Avsluttet gjæring forblir synlig under arkivering; nytt forsøk vises når arkiv mangler/feiler, og Gjør klar følger DB-verifisert eksport.','03-KRAV-DASHBOARD.md:196',244,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-083','DOC-03','ha','active','Gjæringskortet skal vise DB-eid målekildetekst direkte, og synliggjøre feil ved lasting/tegning.','03-KRAV-DASHBOARD.md:202',245,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-084','DOC-03','ha','active','Graf- og demovalg skal nå DB med operation_id. Grafvalg skal bekreftes med akkurat sendt operation_id; periodisk refresh skal ikke tegne om et ventende valg.','03-KRAV-DASHBOARD.md:203',246,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-085','DOC-03','ha','active','Analyse skal også vise SG, temperatur og trykk med delt sammenligning. Analyse- og rapportgrafer skal være om lag 40 prosent høyere.','03-KRAV-DASHBOARD.md:204',247,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-086','DOC-03','ha','active','Teknisk eksport skal tilby kompakt standarddiagnostikk og eksplisitt utvidet diagnostikk med faktisk publisert dashboardgrunnlag; grafvalg og detalj/timeimportens omfang skal følge eksporten.','03-KRAV-DASHBOARD.md:205',248,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-087','DOC-03','ha','active','Graf- og demovalg skal akseptere direkte kommando, payload.data, payload.event og payload.event.data. Det sendte operation_id skal bevares helt til DB-bekreftelse.','03-KRAV-DASHBOARD.md:211',249,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-088','DOC-03','ha','active','Kravlinjer, kravtekst og oppfylt-markeringer i dashboard/rapport skal følge gjeldende kriterierevisjon. Reset bruker originalparametere, eksplisitt tom grense forblir tom, og korrigert stabilitetsvindu knyttes til rett måleserie.','03-KRAV-DASHBOARD.md:212',250,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-089','DOC-03','ha','active','Template og arkiv tilbyr filvalg, forhåndsvisning, import, eksport og separate system-, egen- og importert-kategorier. Historikk kan skjules fra sammenligning uten sletting.','03-KRAV-DASHBOARD.md:218',251,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-090','DOC-03','ha','active','Arkivkortet ligger øverst i Templatefanen og tilbyr aktiv eksport og bekreftet permanent sletting av historiske sesjoner og ubrukte importerte templates.','03-KRAV-DASHBOARD.md:224',252,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-091','DOC-03','ha','active','Ett samlet filvalg leses av backend til en liste etter template-navn. Deretter velges bare template eller template med gjæringsdata. Valg beholdes ved oppdatering; SHA-advarsler vises før import.','03-KRAV-DASHBOARD.md:225',253,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-092','DOC-03','ha','active','Det vanlige startbildet skal tilby «Importer avsluttet gjæring» med sluttidspunkt. Angitt «Start fra», template og første måleserie gjenbrukes. B/P har etterregistrering av manglende faktisk fasestart; alle viste varigheter kommer fra DB.','03-KRAV-DASHBOARD.md:231',254,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-093','DOC-03','ha','active','Sensoriske 0–5-felt vises som heltallsslidere fra DB-metadata. Ikke registrert skal skilles fra registrert 0. Manuell temperatur vises med én desimal; lagret presisjon beholdes.','03-KRAV-DASHBOARD.md:240',255,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-094','DOC-03','ha','active','Målekilder og sensorer plasseres øverst i Teknisk, med DB-kvittert les/kontroller/lagre, HA-valg og sist kontrollerte verdier. Startbildet viser et kompakt kildesammendrag. Pågående redigering overskrives ikke ved bakgrunnsoppdatering.','03-KRAV-DASHBOARD.md:241',256,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-HA-095','DOC-03','ha','active','Teknisk Kilde viser DB-registrert komponentnavn; rå node-/rutineidentitet bevares i detaljer/eksport. Prosesstrinn og Biologi tilbyr samme kriteriekorreksjon og tillatte kriterieavvik fra frozen grunnlag.','03-KRAV-DASHBOARD.md:242',257,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-INST-001','DOC-04','inst','active','Gjeldende dokumentasjon skal bygges som del av samme releasebygg som kode/SQL/kontrakter. Generert HTML er artefakt, ikke separat vedlikeholdt sannhetskilde.','04-KRAV-INSTALLER.md:38',258,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-INST-002','DOC-04','inst','active','Ordinær releasepakke skal ikke inneholde komplett historisk p19-dokumentasjon. Historikk beholdes bare når den uttrykkelig dokumenterer forlatte løsninger eller funksjonelle referanser som fortsatt er relevante.','04-KRAV-INSTALLER.md:39',259,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-INST-003','DOC-04','inst','active','Releaseporten skal bevare testbarhet og relevante regresjons-/arkitekturkontroller, men skal ikke feile på kunstige minimumstall for dokumenter, REQ, DEC eller OPEN.','04-KRAV-INSTALLER.md:40',260,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-INST-004','DOC-04','inst','active','Etter vellykket releaseport skal strukturerte release-testresultater kunne følge pakken og importeres som verifikasjonsfakta ved installasjon.','04-KRAV-INSTALLER.md:41',261,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-INST-005','DOC-04','inst','active','Før databaseendring eller endring av Node-RED-flow skal installeren lese faktisk MariaDB-serverversjon og avvise avvik fra den eksakte verifiserte versjonen i BUILD-INFO.json. Avvisning og observert versjon skal fremgå av installasjonsrapporten.','04-KRAV-INSTALLER.md:42',262,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-INST-006','DOC-04','inst','active','Eksisterende sesjoner, målinger, korreksjoner, templates, kladder, innstillinger og registrerte testresultater skal bevares ved oppgradering. Ukjent kildeversjon/struktur avvises før mutasjon.','04-KRAV-INSTALLER.md:43',263,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_requirements_catalog(requirement_id,document_id,requirement_class,status,statement,source_ref,sort_order,created_at) VALUES ('REQ-INST-007','DOC-04','inst','active','Oppgraderingsmanifest, kilde-/målversjon, migreringsavtrykk, privat verifisert backup og faktisk installasjonsutfall skal være sporbare. Samme målversjon kan reinstallere filer uten å kjøre migreringen på nytt.','04-KRAV-INSTALLER.md:44',264,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE document_id=VALUES(document_id),requirement_class=VALUES(requirement_class),status=VALUES(status),statement=VALUES(statement),source_ref=VALUES(source_ref),sort_order=VALUES(sort_order);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-001','MariaDB/InnoDB er eneste persistente authority.','Én sannhetskilde reduserer divergens og restartproblemer.','Domenestate i flow/global/HA/frontend/runtimefiler er ikke tillatt.','active','14-AKTIVE-BESLUTNINGER.md:14',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-002','Node-RED er generisk gjæringsmotor/orchestrator; HA er operatørflate.','Tydelig ansvarsdeling.','HA skal ikke være domenemotor.','active','14-AKTIVE-BESLUTNINGER.md:15',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-003','`p18-r5` er funksjonell/designmessig referanse, ikke teknisk baseline.','Verdifull funksjon/UX skal kunne sammenlignes uten å gjeninnføre svak implementasjon.','SQLite/writer-kø/lokal runtime-state fra referansen kopieres ikke.','active','14-AKTIVE-BESLUTNINGER.md:16',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-004','Normaliserte domenedata foretrekkes fremfor generiske JSON-event/state-blobs.','Integritet, sporing og DB-validering.','JSON brukes som transport/eksport/read-model, ikke autoritativ runtime.','active','14-AKTIVE-BESLUTNINGER.md:17',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-005','Tetthet er SG-only.','Én entydig domenekontrakt.','Ingen Brix i GUI, template, runtime, rapport, docs eller tester.','active','14-AKTIVE-BESLUTNINGER.md:18',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-007','E2E-/måltest går gjennom den reelle operatør-/integrasjonsgrensen.','Direkte DB/inject kan gi falsk trygghet.','Direkte tester kan være unit/integration, men ikke kalles operatør-E2E.','active','14-AKTIVE-BESLUTNINGER.md:19',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-008','HA-semantikk dokumenteres i 05; eksakte maskinmetadata eies av MariaDB-registre.','Unngå parallelle entity/event-lister.','Generert kontrakt er avledet inspeksjon.','active','14-AKTIVE-BESLUTNINGER.md:20',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-009','Teknisk er operativ observability, ikke bare PASS/FAIL.','Sporadiske runtimefeil må finnes igjen.','Technical Events, aktive issues, målekilde og Systemkontroll vises samlet.','active','14-AKTIVE-BESLUTNINGER.md:21',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-010','`Tilbake` krever advarsel/bekreftelse, ikke obligatorisk begrunnelse.','Operatørflyten skal ikke blokkeres unødig.','Kommentar kan registreres som generelt notat.','active','14-AKTIVE-BESLUTNINGER.md:22',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-011','Publiserte defaults/regler skal være eksplisitte; motor/frontend skal ikke gjette fallback.','Skjulte defaults gjør vurderinger irreproduserbare.','Manglende grunnlag er synlig feil/status.','active','14-AKTIVE-BESLUTNINGER.md:23',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-012','Runtimehistorikk innenfor hver beholdt sesjon er append-only der ny tilstand kan uttrykkes som nytt faktum/revision. Hele historiske sesjoner kan slettes eksplisitt.','Audit og reproduksjon.','Current state utledes i views.','active','14-AKTIVE-BESLUTNINGER.md:24',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-013','Draft-tabeller er eksplisitte mutable arbeidsflater.','Redigering trenger mutabilitet uten å omskrive historikk.','`session_setup_draft`, `measurement_input_draft`, template-draft skilles fra journal.','active','14-AKTIVE-BESLUTNINGER.md:25',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-014','Ingen generell writer-kø eller eksplisitt DB-locking som normalmekanisme.','InnoDB håndterer concurrency; applikasjonslocking øker kompleksitet.','Modell/constraints/transaksjon revurderes før locking innføres.','active','14-AKTIVE-BESLUTNINGER.md:26',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-015','PK/FK/UNIQUE/CHECK, operation-ID og korte transaksjoner er primær konsistensmekanisme.','Konsistens bør ligge nær data.','Applikasjonen bygger på DB-integritet.','active','14-AKTIVE-BESLUTNINGER.md:27',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-016','Kortvarig stale read er akseptabelt.','Normal MVCC/snapshot-adferd trenger ikke global serialisering.','Neste read-model-refresh viser siste commit.','active','14-AKTIVE-BESLUTNINGER.md:28',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-017','Deadlock analyseres som modell/SQL-symptom, ikke maskeres med generell retry.','Retry kan skjule strukturelle feil.','Konkret årsak må forstås før tiltak.','active','14-AKTIVE-BESLUTNINGER.md:29',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-018','Funksjonell verdi prioriteres; teknisk arbeid gjøres når robust funksjon krever det.','Prototypearbeidet skal ikke bli infrastrukturprosjekt.','Teknisk kompleksitet må begrunnes av konkret behov.','active','14-AKTIVE-BESLUTNINGER.md:30',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-019','Runtime-/valideringsmetadata har én autoritativ kilde.','Metadata-duplisering gir drift.','HA-metadata og funksjon↔informasjon-lineage modelleres i MariaDB.','active','14-AKTIVE-BESLUTNINGER.md:31',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-020','Ordinær Start omfatter history catch-up og overgang til kontinuerlig 5-minuttersimport.','Én sammenhengende måleprosess.','Ingen separat «live-start»-modus.','active','14-AKTIVE-BESLUTNINGER.md:32',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-021','`Start fra` er opprinnelig pitch-/importstart; senere pitchkorreksjon omskriver ikke måletimestamps.','Historiske målepunkter må beholde faktisk tid.','Effektiv pitchreferanse kan revideres separat.','active','14-AKTIVE-BESLUTNINGER.md:33',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-022','Eksterne Tilt entity-ID-er eies av `measurement_source_profiles`.','Sensorbinding er konfigurasjon.','Node-RED Function-kode hardkoder ikke entity-ID-er.','active','14-AKTIVE-BESLUTNINGER.md:34',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-023','Heartbeat er autoritativt datadekningssignal.','Uendret SG/temperatur betyr ikke kommunikasjonsbrudd.','Gap bygges fra heartbeat og persisteres i `measurement_data_gaps`.','active','14-AKTIVE-BESLUTNINGER.md:35',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('ADR-GA-024','Registry, template, frozen session og motor har separate ansvar.','Fagregler må være deklarative/reproduserbare.','Registry definerer vokabular; template velger; Start fryser; motor utfører generiske modeller.','active','14-AKTIVE-BESLUTNINGER.md:36',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-025','Metric-ID alene skal ikke gi skjult beregningssemantikk.','Navn er ikke fagregel.','Beregningsmodell/input/parametere er eksplisitte metadata.','active','14-AKTIVE-BESLUTNINGER.md:37',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-026','Freshness og persistens/stabilitet er separate begreper.','De beskriver ulike egenskaper.','Maks alder skal ikke brukes som skjult persistensregel.','active','14-AKTIVE-BESLUTNINGER.md:38',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-027','Biologisk progresjon er sekvensiell; datagap bryter nødvendig kontinuitet.','Hindrer historiske hopp og falsk persistens.','Bare neste B-kandidat vurderes.','active','14-AKTIVE-BESLUTNINGER.md:39',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-028','Målekildestatus har én MariaDB-read-model/produsent.','Konkurrerende produsenter ga stale/motstridende status.','Ingest/Systemkontroll trigger refresh, men lager ikke alternativ status.','active','14-AKTIVE-BESLUTNINGER.md:40',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-029','HA-inputbinding/verdimapping eies av MariaDB.','Entity→domene-felt skal ikke ligge som lokal Function-tabell.','Manglende binding/mapping er konfigurasjonsfeil.','active','14-AKTIVE-BESLUTNINGER.md:41',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-030','Frontend er ren visning/interaksjon av ferdige domenefelt.','GUI-workarounds skjuler kildedefekter.','Ingen domeneberegning/fallback/formatregler i frontend.','active','14-AKTIVE-BESLUTNINGER.md:42',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-031','En metric har én autoritativ beregningsbane.','Parallelle formler gir mismatch.','Overview/B/P/report/Analyse leser persistert resultat/read-model.','active','14-AKTIVE-BESLUTNINGER.md:43',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-032','DB/read-model-feil skal være synlig og rettes ved kilden.','Fail-visible gir bedre arkitektur enn skjult fallback.','GUI/Node-RED skal ikke maskere feil med lokal workaround.','active','14-AKTIVE-BESLUTNINGER.md:44',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-033','Ugyldige råmålinger forkastes før autoritativ domenelagring; de clampes ikke.','Korrigerte oppdiktede data forurenser analysegrunnlaget.','Kvalitetsutfall logges separat.','active','14-AKTIVE-BESLUTNINGER.md:45',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-034','Analysevisualisering og behandlingsregler er datamodell/template-metadata.','Nye grafer skal ikke kreve spesialmotor/frontend.','Graph/series/warm-up/gap/markerpolicy fryses til session.','active','14-AKTIVE-BESLUTNINGER.md:46',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-035','Utilstrekkelig minste beregningsgrunnlag gir ingen verdi; p24r7 krever ordinært faktisk grunnlag.','Unngå oppdiktede tall.','Status, datagrunnlag og stil leveres fra read-model; ordinære krav beholdes.','active','14-AKTIVE-BESLUTNINGER.md:47',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-036','Uncaught teknisk feilfangst er et generelt flow-safety-net.','Nye noder skal ikke falle utenfor «søppelbøtta».','Technical Event-writer/fangstsløyfe skjermes mot rekursjon.','active','14-AKTIVE-BESLUTNINGER.md:48',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-037','Gyldighetsdomene for avledede metrics er domenemetadata og håndheves før B/P og Analyse.','Urimelige derived values skal ikke drive overganger eller grafer.','Output utenfor frozen domene avvises, ikke clampes.','active','14-AKTIVE-BESLUTNINGER.md:49',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-038','Historisk P-autoovergang er per-step frozen policy.','Historikk kan rekonstrueres uten å late som fysisk operatørhandling er utført.','W-34/70 kan autoetablere P1/P2; P3+ krever operatørtransition.','active','14-AKTIVE-BESLUTNINGER.md:50',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-039','Rapport/Gjæring/Analyse bruker autoritative datagap og samme domeneseriegrunnlag.','Linje gjennom manglende data skaper oppdiktet visuell informasjon.','Renderer bryter kurver ved persisterte gap.','active','14-AKTIVE-BESLUTNINGER.md:51',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-040','Normativ dokumentasjon skal beskrive gjeldende sannhet; releasehistorikk holdes separat og maskinmetadata genereres fra kilder.','Historikk i kravdokumenter gjorde dem stale og vanskelige å validere.','Markdown er kilde; HTML/JSON/traceability genereres og releasekontrolleres.','active','14-AKTIVE-BESLUTNINGER.md:52',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-041','Templateadministrasjon er uavhengig av runtime/session.','Frozen sessionplan gjør senere templatearbeid trygt.','Aktiv eller completed session blokkerer ikke templatebibliotek, draft eller publisering.','active','14-AKTIVE-BESLUTNINGER.md:53',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-042','Template lifecycle er `draft/published/retired`, og `retired` er reversibel.','En versjon kan tas ut av Start-utvalget uten å slette historikk eller tvinge ny versjon.','Retired versjon kan reaktiveres; publisert/retired faginnhold er immutable.','active','14-AKTIVE-BESLUTNINGER.md:54',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-043','Template-fanens administrasjonsvalg og Start-fanens templatevalg er separate MariaDB-fakta.','Inspeksjon/redigering skal ikke utilsiktet endre hvilken prosess neste gjæring starter med.','Publisering/åpning i Template-fanen endrer ikke `session_setup_draft`; Start kan kun velge `published`.','active','14-AKTIVE-BESLUTNINGER.md:55',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-044','Verifikasjon modelleres som strukturerte relasjoner i MariaDB.','Krav, verifikasjon og resultater må kunne inspiseres og analyseres uten tekstsøk.','Metadata og faktiske resultater skilles; read-models utleder status.','active','14-AKTIVE-BESLUTNINGER.md:56',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-045','TECH, FUNC og UAT er separate verifikasjonsklasser.','Teknisk integritet, domeneregresjon og målmiljøbruk har ulike testegenskaper.','Testtype og metode er eksplisitt metadata; én type erstatter ikke de andre.','active','14-AKTIVE-BESLUTNINGER.md:57',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-046','Høy testbarhet beholdes selv når hele testpakken ikke kjøres ved hver prototypeendring.','Testarkitektur har verdi, men prototypearbeidet skal ikke styres av testprosess.','Testomfang tilpasses risiko; etablerte regresjonstester bevares.','active','14-AKTIVE-BESLUTNINGER.md:58',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-047','UAT-resultater er append-only verifikasjonsfakta og kan registreres fra dashboardet.','Målmiljøerfaring skal være synlig og analyserbar sammen med krav/testmetadata.','Ny UAT gir ny run/result; tidligere observasjoner overskrives ikke.','active','14-AKTIVE-BESLUTNINGER.md:59',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-048','JSON-eksport og HTML-verifikasjonsrapport produseres fra samme DB-grunnlag.','Maskinanalyse og menneskelesing skal beskrive samme snapshot.','Rapportgeneratoren presenterer; den beregner ikke alternativ verifikasjonsstatus.','active','14-AKTIVE-BESLUTNINGER.md:60',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-049','Komplett p19-dokumentasjon distribueres ikke i p23-release.','Historisk teknisk arkitektur kan forveksles med gjeldende løsning.','Bare eksplisitte baseline-/forlatt-løsning-referanser beholdes.','active','14-AKTIVE-BESLUTNINGER.md:61',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-050','Separat FastAPI/backend-lag og tidligere SQLite-/writer-kø-arkitektur er forlatte løsninger og skal ikke gjeninnføres som workaround.','De økte kompleksitet og ga flere sannhetskilder/concurrencyproblemer uten funksjonell gevinst.','Gjeldende p24 er Node-RED ↔ MariaDB direkte med InnoDB/constraints/transaksjoner og DB-eide read-models.','active','14-AKTIVE-BESLUTNINGER.md:62',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-051','B/P og detaljbasert Analyse bruker samme målebaserte modell; historiske timeverdier er separat grafgrunnlag.','Samme beregningsgrunnlag og terskler.','Ordinære verdier og datagrunnlag persisteres append-only; utilstrekkelig grunnlag gir fravær.','active','14-AKTIVE-BESLUTNINGER.md:64',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-052','Bånd er størrelsens metadata, ikke en universell grafregel.','Et bånd må ha konkret fysisk/statistisk betydning.','P24r7-AA/rate/stabilitet har ingen estimert bånd. Oversiktsgrafer kan vise faktisk min/maks-spredning fra samme godkjente prøvesett.','active','14-AKTIVE-BESLUTNINGER.md:65',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-053','Biologisk fase endres gjennom kriterievurdering.','En fase skal kunne forklares fra sitt grunnlag.','Direkte fasesetter fjernes; korreksjon/fravik er egne append-only fakta.','active','14-AKTIVE-BESLUTNINGER.md:66',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-054','Modellens tillatte kriterieparametere er korrigerbare og fravik tillatt som standard.','Operatøren trenger konsistent håndtering på B og P.','Editor kan deaktivere rettigheter; Start fryser policyen.','active','14-AKTIVE-BESLUTNINGER.md:67',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-GA-055','Alle gjæringsgrafer starter ved effektiv pitch.','Sammenlignbar oppstart og synlig ventetid.','DB/read-model leverer felles X-akse til dashboard og rapporter.','active','14-AKTIVE-BESLUTNINGER.md:68',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-P24R6-001','Målebasert Analyse og filverifisert eksport','Manglende pitchhistorikk og store SQL-pakker blokkerte bruk','Separate rå/manuelle AA-kilder, målt endepunktrate, ordinære vinduer, metadata-only eksportregistrering og append-only retry.','active','14-AKTIVE-BESLUTNINGER.md:70',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-P24R8-TRANSPORT','Felles presentasjonsordbok og komprimert publisering','Gjentatt metadata var hovedårsaken til store filer.','Ingen råmålinger slettes ved transportkomprimering; DB styrer utvalg og verdier.','active','14-AKTIVE-BESLUTNINGER.md:72',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-P24R9-CURRENT','Importbehov og gjeldende grafkrav utledes i MariaDB.','Gjentatt statistikkhenting og gamle kravlinjer ga misvisende visning.','Normal live-import henter detaljdata; parameterkorreksjon/reset og oppfylt-markører følger DB-revisjonen. Tidligere målinger og evalueringer beholdes.','active','14-AKTIVE-BESLUTNINGER.md:74',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-P24R10-ARCHIVES','Gjærings- og originaltemplate-arkiv er et sammenhørende SQLite-par.','Filer skal være søkbare og kunne importeres uten å sende store JSON-pakker til DB.','All runtime authority og all sammenligning ligger fortsatt i MariaDB.','active','14-AKTIVE-BESLUTNINGER.md:80',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-P24R10-IMPORT','Importert original får ny identitet og egen kategori; historisk import frigir sesjonen atomisk.','Kilden skal ikke blandes med eksisterende templates eller aktiv gjæring.','Import er tillatt under gjæring; feil ruller tilbake hele settet og redigering krever egen kopi.','active','14-AKTIVE-BESLUTNINGER.md:81',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-P24R11-DELETE','Append-only gjelder innholdet i hver beholdt sesjon, ikke hele databasen.','Gamle sesjoner skal kunne ryddes etter eksport eller sammenligning.','Eksplisitt sletting av hele sesjonen i én transaksjon, med aktivbeskyttelse og referansekontroll for templates.','active','14-AKTIVE-BESLUTNINGER.md:87',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-P24R11-SNAPSHOT','Alle eksportfiler for en sesjon bygger på ett konsistent MariaDB-snapshot.','Aktiv drift skal kunne fortsette mens arkivet lages.','SQLite-par, HTML og SHA-filer deler prefix; aktivt øyeblikksbilde merkes med tidspunkt.','active','14-AKTIVE-BESLUTNINGER.md:88',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-P24R11-SHA','Eksterne SHA-filer er en valgfri kontroll med advarsel.','Gamle eller flyttede arkiver skal fortsatt kunne importeres.','Manglende/feil SHA blokkerer ikke import; intern integritet og faktisk overføring valideres obligatorisk.','active','14-AKTIVE-BESLUTNINGER.md:89',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-RELEASE-001','Datoversjon ÅÅÅÅ.MM.DD-N, v-prefiks på tag og kort releasebeskrivelse.','Entydig publiseringsdag og identitet uten prototype-serier.','Løpenummer starter på 1 hver publiseringsdag; prosjektversjon samordnes i leveranse- og runtime-metadata.','active','14-AKTIVE-BESLUTNINGER.md:95',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-WORK-001','Avklaring i chat, «start», implementering og relevante kontroller; direkte commit på main.','Dagens avtalte prosjektarbeidsmåte.','Issues/PR og den gamle Chat→Work-handoff-prosessen videreføres ikke.','active','14-AKTIVE-BESLUTNINGER.md:96',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-PROD-001','Installasjon bevarer eksisterende data; verifiserte migreringer erstatter prototype-reset.','Brukeren tar løsningen i ordinær drift.','Førstegangsseeding kjøres bare på tom database. Privat backup før oppgradering; ukjent kilde avvises. Erstatter tidligere DEC-GA-006.','active','14-AKTIVE-BESLUTNINGER.md:102',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-START-001','Startfelt, mangler og startklarstatus eies av databasekladden og DB-registre.','Gamle HA-tall kunne skjule NULL etter nytt templatevalg.','Generisk DB-basert skjema sender eksplisitte feltkommandoer; ingen HA-fallback eller null-til-nulltall. Startforsøk lagrer observerte felt og DB-avvisning.','active','14-AKTIVE-BESLUTNINGER.md:103',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-SOURCES-001','DB-eide reviderte signalbindinger, fryst per sesjon og virkning fra neste DB-bøttegrense ved livebytte.','Kildebytter må være sporbare uten å omskrive tidligere data.','HA-katalog er kontrollert teknisk snapshot; NR transporterer. Valgfritt overtrykk bruker DB-deklarert enhet/konvertering og er manuelt før valg.','active','14-AKTIVE-BESLUTNINGER.md:109',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_decisions_catalog(decision_id,decision,rationale,consequence,status,source_ref,created_at) VALUES ('DEC-OPERATOR-001','Feltkontroll og desimaler følger DB-registeret; B/P-avvik bruker samme autoritative transaksjon.','Synlig verdi, mangler og tillatte handlinger må stemme med DB.','Slider har eksplisitt ikke registrert og registrert 0. Kildenavn er lesbare mens rå identitet bevares.','active','14-AKTIVE-BESLUTNINGER.md:110',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE decision=VALUES(decision),rationale=VALUES(rationale),consequence=VALUES(consequence),status=VALUES(status),source_ref=VALUES(source_ref);
INSERT INTO verification_definitions(verification_id,verification_type,title,acceptance_criterion,status,created_at) VALUES ('VER-TECH-001','technical','Autoritativ MariaDB-arkitektur','Releasekilden har én MariaDB-authority og ingen persistent domenestate/fallback i flow/global/frontend.','active',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE verification_type=VALUES(verification_type),title=VALUES(title),acceptance_criterion=VALUES(acceptance_criterion),status=VALUES(status);
