INSERT INTO verification_definitions(verification_id,verification_type,title,acceptance_criterion,status,created_at) VALUES ('VER-TECH-002','technical','HA-kontrakt og metadata-lineage','HA entity/event-register, systemfunksjoner og required lineage er konsistente med fysisk flow/dashboard.','active',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE verification_type=VALUES(verification_type),title=VALUES(title),acceptance_criterion=VALUES(acceptance_criterion),status=VALUES(status);
INSERT INTO verification_requirement_links(requirement_id,verification_id,required,created_at) VALUES ('REQ-COM-063','VER-TECH-002',1,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE required=VALUES(required);
