INSERT INTO verification_definitions(verification_id,verification_type,title,acceptance_criterion,status,created_at) VALUES ('VER-TECH-003','technical','Read-model authority','Aktive runtime views eksisterer og Node-RED leser felter som viewkontrakten faktisk leverer.','active',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE verification_type=VALUES(verification_type),title=VALUES(title),acceptance_criterion=VALUES(acceptance_criterion),status=VALUES(status);
INSERT INTO verification_requirement_links(requirement_id,verification_id,required,created_at) VALUES ('REQ-MOTOR-035','VER-TECH-003',1,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE required=VALUES(required);
INSERT INTO verification_requirement_links(requirement_id,verification_id,required,created_at) VALUES ('REQ-MOTOR-049','VER-TECH-003',1,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE required=VALUES(required);
INSERT INTO verification_definitions(verification_id,verification_type,title,acceptance_criterion,status,created_at) VALUES ('VER-TECH-004','technical','Release/dokumentasjon','Releasepakke, dokumentkilder og genererte artefakter er versjonskonsistente og reproducerbare uten historisk p19-dokumentkrav.','active',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE verification_type=VALUES(verification_type),title=VALUES(title),acceptance_criterion=VALUES(acceptance_criterion),status=VALUES(status);
INSERT INTO verification_requirement_links(requirement_id,verification_id,required,created_at) VALUES ('REQ-INST-001','VER-TECH-004',1,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE required=VALUES(required);
INSERT INTO verification_requirement_links(requirement_id,verification_id,required,created_at) VALUES ('REQ-INST-002','VER-TECH-004',1,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE required=VALUES(required);
