INSERT INTO verification_tests(test_id,test_type,title,description,method_type,implementation_ref,automated,status,sort_order,created_at) VALUES ('TEST-FUNC-017','FUNC','SQLite eksport/import og aktiv drift','Normalisert par, atomisk rollback og måleskriving under import på MariaDB 12.3.3. P24r11: aktivt snapshot med SHA/rapport, kontrollsumadvarsler, permanent sletting, aktivbeskyttelse og rollback.','node_integration','tests/test-sqlite-live.js',1,'active',41,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE test_type=VALUES(test_type),title=VALUES(title),description=VALUES(description),method_type=VALUES(method_type),implementation_ref=VALUES(implementation_ref),automated=VALUES(automated),status=VALUES(status),sort_order=VALUES(sort_order);
