INSERT INTO verification_tests(test_id,test_type,title,description,method_type,implementation_ref,automated,status,sort_order,created_at) VALUES ('TEST-FUNC-023','FUNC','DB-eid Systemkontroll, datadekning og HA-gjenoppkobling','Rapporttilfelle med kun timehistorikk, DB-policy/manglende kontrakt, deduplisering uten feilsirkel, ferske DB-retries og faktisk plugin-controllerutgang som kvittering. Simulert HA-transport, ikke målmiljø-UAT.','node_integration','tests/test-p24r16-system-live.js',1,'active',49,UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE test_type=VALUES(test_type),title=VALUES(title),description=VALUES(description),method_type=VALUES(method_type),implementation_ref=VALUES(implementation_ref),automated=VALUES(automated),status=VALUES(status),sort_order=VALUES(sort_order);
