INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-009',1,'Åpne Verifikasjon-fanen og velg en aktiv UAT-test.','Testen viser DB-eid gjeldende status og tilknyttede krav/verifikasjonskrav.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-009',2,'Registrer resultat med operatørnavn og notat.','Ny DB-kvittert run/result opprettes og tidligere resultat beholdes i historikken.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-010',1,'Velg Generer verifikasjonseksport.','Både JSON- og HTML-fil publiseres under HA-public exports.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-010',2,'Åpne begge filer.','Versjon, tidspunkt, krav, verifikasjoner, tester og resultater beskriver samme DB-snapshot.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-011',1,'Ha en aktiv reell gjæring og noter session-ID, biologisk fase, prosesstrinn, siste importcursor og målekildestatus fra MariaDB/read-model.','Referansetilstanden er DB-kvittert før restart.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-011',2,'Restart vertsmaskinen eller de tre modulene slik at MariaDB, Node-RED og Home Assistant ikke er tilgjengelige samtidig i oppstartsøyeblikket. Ikke trykk Start eller restart Node-RED manuelt etterpå.','Systemet tåler vilkårlig oppstartsrekkefølge og retry/reconcile fortsetter til avhengighetene er tilgjengelige.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-011',3,'Når alle moduler er oppe, kontroller Gjæring, Biologi, Prosesstrinn, målekilde og MariaDB.','Samme session, B-fase og P-trinn er rekonstruert fra MariaDB; HA-projeksjonene er repopulert uten ny Start eller dupliserte overgangsfakta.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-011',4,'Kontroller live-import etter reconnect.','Import fortsetter fra persistert last_import_cutoff_at og går tilbake til LIVE uten dupliserte 5-minuttersbøtter eller domenhistorikk.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-014',1,'Eksporter et avsluttet brygg og importer det sammenhørende SQLite-paret mens en annen gjæring pågår.','Filvalg/forhåndsvisning/import fungerer i faktisk HA, målingene fortsetter og importert gjæring kan velges i sammenligning.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-014',2,'Kontroller template-kategorier, kopier importert original til ny egen ID, og skjul/vis importert historikk.','Originalen forblir separat og skrivebeskyttet. Egen kopi kan redigeres; sammenligningslisten følger DB-kvittert synlighet.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-014',3,'Demo → Avslutt → Gjør klar → velg template → Start ordinær gjæring. Restart Node-RED.','Start er tilgjengelig igjen; status rekonstrueres fra MariaDB.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-014',4,'Eksporter aktivt øyeblikksbilde med SHA/HTML. Velg filene samlet og prøv feil/manglende SHA før import.','Aktiv drift fortsetter; advarsel vises uten importblokkering; valgene beholdes.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-014',5,'Slett historisk sesjon fra MariaDB, deretter ubrukt importert template; prøv sletting med brukt template.','Komplett sletting, nullstilt sammenligning, beholdte eksportfiler og avvisning av brukte templates.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-014',6,'Velg template og historisk Start fra med første måleserie. Angi sluttid og importer avsluttet gjæring fra faktisk HA.','Kun valgt fra–til behandles, siste deltime bruker bare tilgjengelig detaljgrunnlag, og kilden viser HISTORISK etter fullføring.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-014',7,'Etterregistrer en manglende B- og P-start, og flytt en eksisterende start. Registrer målerunde med faktisk historisk måletid og et kriterieavvik.','Begge nabovarigheter og grensene oppdateres fra DB; vurderingen bruker historisk horisont, og avvik/registreringstid bevares.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
INSERT INTO verification_uat_steps(test_id,step_order,instruction,expected_result,created_at) VALUES ('TEST-UAT-014',8,'Start Node-RED på nytt etter ferdig import, kontroller tidslinjen neste dag og eksporter SQLite/SHA/HTML.','Ingen videre Tilt-henting, uendret historisk slutt og korrekt rapport/arkiv med etterregistreringene.',UTC_TIMESTAMP(3)) ON DUPLICATE KEY UPDATE instruction=VALUES(instruction),expected_result=VALUES(expected_result);
